#include <cstdio>
#include <numeric> // for std::gcd

using namespace std;

typedef long long ll;

int main() {
    int n;
    ll d[10], v[10], t[10];

    for (;;) {
        scanf("%d", &n);
        if (!n) break;

        for (int i = 0; i < n; i++) scanf("%lld%lld", &d[i], &v[i]);
        t[0] = 1;

        for (int i = 1; i < n; i++) {
            t[i] = t[i - 1] * d[i - 1] * v[i];
            ll common_gcd = t[i]; // Initialize with t[i] for gcd calculation
            for (int j = 0; j < i; j++) {
                t[j] *= d[i] * v[i - 1];
                common_gcd = std::gcd(common_gcd, t[j]); // Calculate gcd on-the-fly
            }
            for (int j = 0; j <= i; j++) t[j] /= common_gcd; // Simplify all t[j] using common_gcd
        }

        for (int i = 0; i < n; i++) printf("%lld\n", t[i]);
    }
}

