#include <iostream>
#include <vector>
#include <thread>
#include <future>

using namespace std;

typedef long long ll;

ll gcd(ll a, ll b) {
    return (!b) ? a : gcd(b, a % b);
}

void computeGcdAndUpdate(int n, vector<ll>& d, vector<ll>& v, vector<ll>& t) {
    t[0] = 1;

    for (int i = 1; i < n; i++) {
        t[i] = t[i - 1] * d[i - 1] * v[i];
        for (int j = 0; j < i; j++) t[j] *= d[i] * v[i - 1];

        ll T = t[0];
        for (int j = 1; j <= i; j++) T = gcd(T, t[j]);
        for (int j = 0; j <= i; j++) t[j] /= T;
    }
}

int main() {
    int n;
    vector<ll> d, v, t;

    for (;;) {
        cin >> n;
        if (!n) break;

        d.resize(n);
        v.resize(n);
        t.resize(n);
        for (int i = 0; i < n; i++) cin >> d[i] >> v[i];

        // Launching a thread to perform computations
        thread computeThread(computeGcdAndUpdate, n, ref(d), ref(v), ref(t));
        computeThread.join(); // Wait for the thread to finish

        for (int i = 0; i < n; i++) cout << t[i] << endl;
    }
}

